# -*- coding: utf-8 -*-
"""Обновление строк пяти дисциплин в README.md по summary.json (его пишет docs5d.py)."""
import os, re, sys, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import ROOT, DISC, D5
os.chdir(ROOT)
S = {r['code']: r for r in json.load(open(D5 + 'summary.json', encoding='utf-8'))}
Q = {'upp': 'два перечня: к экзамену — 66 вопросов, к зачёту — 87 (совпадают 21 формулировка)', 'up': 'два перечня: 107 вопросов и 93 вопроса (общая часть — 50, особенная — 43)',
     'gpp': 'перечень из 52 вопросов', 'tp': 'перечень из 70 вопросов', 'tsp': 'перечень: 60 пронумерованных вопросов и 44 без номеров (в базе — Д1–Д44)'}
lines = open('README.md', encoding='utf-8').read().split('\n')
for i, l in enumerate(lines):
    for code, d in DISC.items():
        if l.startswith('| `%s` |' % d['dir']):
            r = S[code]
            lines[i] = ('| `%s` | база источников собрана 15.11.2026, дополнена 16.11.2026: %s; источники права — %d (нормативные акты — %d, судебная практика — %d); учебные издания — %d, научные издания — %d, '
                        'статьи 2023–2026 годов — %d (с отметкой ВАК — %d), эмпирические материалы — %d; привязка к вопросам автоматическая, по ключевым словам; что не найдено — в разделе Б файла '
                        '`2. Источники/Реестр источников.md`; справка по вопросам — `2. Источники/Литература и материалы по вопросам.md` |') % (
                d['dir'], Q[code], r['acts'] + r['court'], r['acts'], r['court'], r['books'], r['sci'], r['arts'], r['vak'], r['emp'])
txt = '\n'.join(lines)
txt = re.sub(r'Подробная разбивка папки «Источники» сделана для[^\n]*?по дисциплине\.', 'Базы источников собраны по всем семи дисциплинам; подробная разбивка папки «Источники» у дисциплин немного различается (см. «Реестр источников» каждой).', txt)
open('README.md', 'w', encoding='utf-8').write(txt)
print('README обновлён')
